package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.repository.*; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.*;
@Service public class BenefitServiceImpl implements BenefitService{
 private final BenefitPlanRepository plans; private final BenefitEnrollmentRepository enrollments;
 public BenefitServiceImpl(BenefitPlanRepository p,BenefitEnrollmentRepository e){plans=p;enrollments=e;}
 public List<BenefitPlan> plans(boolean all){return all?plans.findAll():plans.findByActiveTrueOrderByCategoryAscPlanNameAsc();}
 public BenefitPlan savePlan(BenefitPlan p){if(p.getPlanCode()==null||p.getPlanCode().isBlank()||p.getPlanName()==null||p.getPlanName().isBlank())throw new IllegalArgumentException("Plan code and name are required.");return plans.save(p);}
 public void deletePlan(Long id){if(enrollments.findAll().stream().anyMatch(e->e.getBenefitPlan()!=null&&Objects.equals(e.getBenefitPlan().getId(),id)&&"ACTIVE".equals(e.getStatus())))throw new IllegalStateException("Active enrollments exist for this plan. Deactivate the plan instead.");plans.deleteById(id);}
 public List<BenefitEnrollment> myEnrollments(String u){return enrollments.findByUserIdOrderByCreatedAtDesc(u);} public List<BenefitEnrollment> allEnrollments(){return enrollments.findAllByOrderByCreatedAtDesc();}
 public BenefitEnrollment enroll(Long pid,BenefitEnrollment e,String u,String n){BenefitPlan p=plans.findById(pid).orElseThrow(()->new NoSuchElementException("Benefit plan not found."));if(!Boolean.TRUE.equals(p.getActive()))throw new IllegalArgumentException("Benefit plan is inactive.");if(enrollments.findByUserIdAndBenefitPlan_Id(u,pid).isPresent())throw new IllegalArgumentException("You are already enrolled in this plan.");e.setId(null);e.setUserId(u);e.setEmployeeName(n);e.setBenefitPlan(p);e.setStatus("ACTIVE");if(e.getEffectiveDate()==null)e.setEffectiveDate(p.getEffectiveFrom()!=null?p.getEffectiveFrom():LocalDate.now());return enrollments.save(e);}
 public BenefitEnrollment update(Long id,BenefitEnrollment e,String u){BenefitEnrollment x=enrollments.findById(id).orElseThrow();if(!Objects.equals(x.getUserId(),u))throw new IllegalStateException("You can only update your own enrollment.");if(!"ACTIVE".equals(x.getStatus()))throw new IllegalStateException("Only active enrollment can be updated.");x.setDependentName(e.getDependentName());x.setDependentRelationship(e.getDependentRelationship());x.setEmployeeComment(e.getEmployeeComment());return enrollments.save(x);}
 public BenefitEnrollment review(Long id,String s,String c,String r){BenefitEnrollment x=enrollments.findById(id).orElseThrow();if(!Set.of("ACTIVE","CANCELLED","REJECTED").contains(s))throw new IllegalArgumentException("Invalid enrollment status.");x.setStatus(s);x.setReviewedBy(r);x.setReviewComment(c);x.setReviewedAt(java.time.LocalDateTime.now());return enrollments.save(x);}
 public void cancel(Long id,String u){BenefitEnrollment x=enrollments.findById(id).orElseThrow();if(!Objects.equals(x.getUserId(),u))throw new IllegalStateException("You can only cancel your own enrollment.");if(!"ACTIVE".equals(x.getStatus()))throw new IllegalStateException("Only active enrollment can be cancelled.");x.setStatus("CANCELLED");enrollments.save(x);}
}
